use vstd::prelude::*;

verus! {

    // Reverse the contents of `v` in‐place.
    // Postcondition: the length is unchanged, and the resulting sequence
    // is the reverse of the original.
    fn reverse(v: &mut Vec<u64>)
        ensures
            // length unchanged
            v.len() == old(v.len()),
            // content reversed
            v@ == old(v@).reversed(),
    {
        let n_usize = v.len();
        // Trivial cases: empty or single‐element vector
        if n_usize <= 1 {
            return;
        }

        // Work in `nat` for the proofs
        let n: nat = n_usize as nat;
        let mut left:  nat = 0;
        let mut right: nat = n - 1;

        // We will swap `v[left]` with `v[right]` until left >= right.
        // Loop invariants capture the part already reversed and the part
        // still untouched.
        while left < right
            invariant left <= right + 1,   // so that (right+1-left) is a nat
            invariant right < n,
            // For all indices i < left, we have already reversed them:
            invariant forall |i: nat| i < left ==>
                        v@[i] == old(v@)[n - 1 - i],
            // For all indices i > right, we have already reversed them:
            invariant forall |i: nat| right < i && i < n ==>
                        v@[i] == old(v@)[n - 1 - i],
            // For all indices between left and right (inclusive), we
            // have not yet touched them:
            invariant forall |i: nat| left <= i && i <= right ==>
                        v@[i] == old(v@)[i],
            // Measure decreases each iteration: (right+1 - left)
            decreases (right + 1 - left),
        {
            // swap the two outer elements
            v.swap(left as usize, right as usize);
            // move inward
            left  = left  + 1;
            right = right - 1;
        }
    }

}    

